--
-- Table structure for table `permissions`
--

DROP TABLE IF EXISTS `permissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `permissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `date` date NOT NULL,
  `day` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `permission_type` varchar(255) DEFAULT NULL,
  `reason` text NOT NULL,
  `from` time DEFAULT NULL,
  `to` time DEFAULT NULL,
  `status` enum('pending','accepted','refused') NOT NULL DEFAULT 'pending',
  `refuse_reason` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `created_ip` varchar(45) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `alarm` tinyint(1) NOT NULL DEFAULT 0,
  `actioned_by` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `permissions_user_id_foreign` (`user_id`),
  KEY `permissions_date_index` (`date`),
  KEY `permissions_status_index` (`status`),
  CONSTRAINT `permissions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

